B.bnU=new A.tb("none","Nothing happens: the device gets no power.",!1,!1,!1)
B.bnV=new A.tb("none","It cannot be judged: the wire functions were not verified.",!1,!1,!1)
B.bnW=new A.tb("smoke","The loose connection overheats: it glows, smokes and chars the device. In a real wall this can start a fire.",!1,!1,!0)
B.bnX=new A.tb("none","It does not work as it should: some part runs wrongly or not at all. That does not tell you what is wrong, so check against the diagram.",!1,!1,!1)
B.bnY=new A.tb("none","It runs. There is nothing to see, and that is the danger: with no ground, a fault would energize the metal parts.",!0,!1,!1)
