B.bo_=new A.tb("none","It works, and every safety rule is met.",!0,!1,!1)
B.bo0=new A.tb("none","Nothing happens: it is dead. But the hot wire is connected, so it can still be live. No sparks, no smoke: that does not make it safe.",!1,!1,!1)
B.bo1=new A.tb("spark","Bare copper touches something it should not: sparks. The circuit is not safe.",!1,!1,!1)
B.bo2=new A.tb("none","It looks fine for now. But the support cannot carry the weight, and it can fall later.",!1,!1,!1)
B.bo3=new A.tb("fire","BANG. A short circuit: a flash, sparks, smoke and a flame at the device. The breaker trips and the device is ruined. The wires and the device are not safe to use.",!1,!0,!0)
B.bo4=new A.tb("arc","Hot and neutral are reversed: the parts that should be dead are live. Blue arcs show the energized metal. The simulator does not let anything run on this: it is unsafe, even if a real appliance might seem to work.",!1,!1,!1)
B.bo5=new A.tb("arc","Current flows through the ground wire and the metal parts it joins. Arcs crackle at the box. This is a shock hazard.",!1,!1,!1)
B.bo6=new A.tb("spark","The neutral and ground are joined: the protective device trips with a snap of sparks.",!1,!0,!1)
