B.bVO=new A.jF("Breaker off, then test","Before you touch any wire, switch its breaker OFF, then check with a voltage tester that the wire is dead. A switch on the wall is not enough.")
B.bVB=new A.jF("Lock out, tag out","On a real job you put a lock or a note on the panel so nobody switches the power back on while you work.")
B.bVV=new A.jF("Water and power","Water carries electricity. Near sinks, tubs and outdoors the outlets must be GFCI, and wet hands never touch wires.")
B.bVG=new A.jF("Eyes, ears, lungs","Safety glasses for drilling and cutting, ear protection for loud tools, and a mask when you sand drywall dust or cut tile.")
B.bVU=new A.jF("Shut the water off","Before you cut or loosen a pipe, close the main water valve and open a faucet to drain the line.")
B.dcd=w([B.bVO,B.bVB,B.bVV,B.bVG,B.bVU],x.Z)
B.bW6=new A.MB("Safety first","\ud83e\uddba",D.c9,B.dcd)
B.bVW=new A.jF("Wire colours","Black is hot (it carries the power), white is neutral (the way back), bare copper or green is ground (the safety path). Red is a second hot, often used for a switched line.")
B.bW2=new A.jF("Screw colours","On an outlet the brass screw takes the hot wire, the silver screw takes the neutral and the green screw takes the ground.")
B.bVQ=new A.jF("Wire size","14 gauge wire is for 15 amp circuits (lights and outlets). 12 gauge is for 20 amp circuits (kitchens). A thinner wire than the breaker allows can overheat and start a fire.")
B.bVK=new A.jF("Breakers","A breaker is a safety switch. It trips when a circuit carries too much current, so the wires never get hot enough to burn.")
B.bVY=new A.jF("Wire nuts","Strip about 3/4 inch, twist the bare ends together clockwise, and screw on the nut until no bare copper shows. Give each wire a gentle tug.")
B.bW3=new A.jF("Switches","A switch cuts the hot wire only. The neutral goes straight through to the light.")
B.bW4=new A.jF("GFCI","A GFCI outlet watches the current going out and coming back. If a little leaks (through water or a person) it cuts the power in a fraction of a second.")
B.bVD=new A.jF("Ceiling fans","A fan shakes and is heavy. It needs a box that says fan rated, fixed to the joist, not a plain light box.")
B.bVF=new A.jF("Heights","Outlets sit about 16 inches from the floor. Switches sit about 48 inches up, where your hand falls.")
B.d4H=w([B.bVW,B.bW2,B.bVQ,B.bVK,B.bVY,B.bW3,B.bW4,B.bVD,B.bVF],x.Z)
B.bW9=new A.MB("Wiring basics","\u26a1",D.bH,B.d4H)
B.bVC=new A.jF("Hot left, cold right","On a faucet, hot is on the left and cold on the right. Hot lines are marked red and cold lines blue.")
B.bVP=new A.jF("The P-trap","The curved pipe under a sink always holds a little water. That water seal stops sewer gas coming up the drain.")
B.bW_=new A.jF("Shut-off valves","Every sink and toilet has its own small valve, so you can stop the water to one fixture without turning off the whole house.")
B.bVI=new A.jF("Slip nuts","Drain joints are sealed by a washer and a slip nut. Tighten by hand and a quarter turn: too much force cracks plastic.")
B.bVH=new A.jF("Wax ring","A toilet sits on a wax ring that seals it to the floor drain. A toilet is lowered straight down once, and cannot be slid around.")
B.bVX=new A.jF("Drain slope","Drains fall about 1/4 inch per foot so water and waste keep moving. Too flat and it clogs, too steep and the water leaves the solids behind.")
B.bW1=new A.jF("Order of work","Plumbing goes from the top down on the drain (tailpiece, trap, arm) and from the wall out on the supply (valve, hose, fixture).")
B.ccM=w([B.bVC,B.bVP,B.bW_,B.bVI,B.bVH,B.bVX,B.bW1],x.Z)
B.bW7=new A.MB("Plumbing basics","\ud83d\udeb0",D.cl,B.ccM)
B.bVE=new A.jF("Studs","Studs are the vertical 2x4 posts inside a wall, 16 inches apart from centre to centre. Everything is fixed to them.")
B.bVS=new A.jF("Drilling studs","Holes for cable go through the middle of the stud, so a nail or screw cannot reach the wire.")
B.bVJ=new A.jF("Drywall","A sheet is 4 feet wide, so its edges land on studs 48 inches apart. Screws go into studs only, just under the paper.")
B.bVM=new A.jF("Taping and mud","Seams get paper tape and three thin coats of joint compound, sanded smooth between coats, then primer and paint.")
B.bW0=new A.jF("Order of a build","Frame, run the pipes and wires (rough-in), inspect, hang drywall, finish it, paint, then fit the fixtures and devices.")
B.cR5=w([B.bVE,B.bVS,B.bVJ,B.bVM,B.bW0],x.Z)
B.bW5=new A.MB("Framing and walls","\ud83c\udfe0",D.dU,B.cR5)
B.bVN=new A.jF("Voltage tester","A pen that glows or beeps near live wires. Test it on a known live outlet first, so you know it works.")
B.bVT=new A.jF("Wire strippers","Strip the plastic off without nicking the copper. A nick weakens the wire.")
B.bVZ=new A.jF("Adjustable wrench","For nuts on valves and hoses. Hold the fitting steady with a second wrench so you do not twist the pipe.")
B.bVR=new A.jF("Drill and screw gun","A drill makes holes through studs. A screw gun sets drywall screws to the right depth.")
B.bVL=new A.jF("Level and tape measure","Measure twice, cut once. A level makes sure outlets, shelves and pipes are straight.")
B.dkj=w([B.bVN,B.bVT,B.bVZ,B.bVR,B.bVL],x.Z)
